'piggy-bank':'<path d="M19 5a5 5 0 0 0-2.5.7A8 8 0 0 0 4 11H2v5h3l2 4h3l1-2h4l1 2h3l1-4a8 8 0 0 0 1-4V9h-2V5Z"/><path d="M9 9h.01"/>',
